vec4 proceduralColor(vec4 c,vec3 p,vec3 n,vec2 uv) {
    vec3 v=normalize(eye-p);float fresnel=0.02+0.98*pow(1.0-abs(dot(n,v)),5.0);
    vec3 reflected=reflect(-v,n);
    vec3 sky=mix(vec3(0.30,0.48,0.62),vec3(0.76,0.88,0.98),clamp(reflected.y*0.5+0.5,0.0,1.0));
    float ripple=0.5+0.5*sin(localPosition.x*2.3+localPosition.z*1.7+time*u_speed);
    vec3 water=mix(u_deepColor.rgb,u_shallowColor.rgb,ripple*0.45+0.2);
    float foam=u_foam*smoothstep(0.70,0.98,1.0-abs(n.y));
    return vec4(mix(mix(water,sky,fresnel),vec3(0.92,0.98,1),foam),u_opacity);
}

float patternHash(vec3 p) { return fract(sin(dot(p,vec3(127.1,311.7,74.7))+float(u_seed)*0.137)*43758.5453); }
float patternNoise(vec3 p) {
    vec3 i=floor(p),f=fract(p);f=f*f*(3.0-2.0*f);
    return mix(mix(mix(patternHash(i),patternHash(i+vec3(1,0,0)),f.x),mix(patternHash(i+vec3(0,1,0)),patternHash(i+vec3(1,1,0)),f.x),f.y),mix(mix(patternHash(i+vec3(0,0,1)),patternHash(i+vec3(1,0,1)),f.x),mix(patternHash(i+vec3(0,1,1)),patternHash(i+vec3(1,1,1)),f.x),f.y),f.z);
}
// Derivative bump mapping works on arbitrary source triangles and transformed instances.
vec3 patternBump(vec3 n,float h) {
    vec3 dpdx=dFdx(worldPosition),dpdy=dFdy(worldPosition);
    vec3 r1=cross(dpdy,n),r2=cross(n,dpdx);
    float det=dot(dpdx,r1);
    if(abs(det)<1e-10)return n;
    return normalize(abs(det)*n-sign(det)*(dFdx(h)*r1+dFdy(h)*r2));
}

// Inverse rotation maps source-local coordinates into the oriented pattern frame.
// Pattern orientation is Rv * Ru; defaults preserve existing material appearance.
vec3 patternCoordinates(vec3 p) {
    vec2 a=radians(vec2(u_rotationU,u_rotationV));
    float cu=cos(a.x),su=sin(a.x),cv=cos(a.y),sv=sin(a.y);
    p=vec3(cv*p.x-sv*p.z,p.y,sv*p.x+cv*p.z);
    return vec3(p.x,cu*p.y+su*p.z,-su*p.y+cu*p.z);
}

vec2 brickUv() {
    vec3 n=abs(patternCoordinates(sourceNormal));
    vec3 p=patternCoordinates(localPosition);
    if(n.y>n.x&&n.y>n.z)return p.xz;
    return n.x>n.z?p.zy:p.xy;
}
vec3 brickPattern() {
    vec2 size=vec2(u_brickWidth,u_brickHeight),p=brickUv()/size;
    float row=floor(p.y);p.x+=mod(row,2.0)*u_stagger;
    vec2 cell=floor(p),f=fract(p),edge=min(f,1.0-f)*size;
    float gap=u_mortar*min(size.x,size.y)*0.5;
    float aa=max(length(fwidth(brickUv())),0.00001);
    float inside=smoothstep(gap-aa,gap+aa,min(edge.x,edge.y));
    float variation=patternHash(vec3(cell,float(u_seed)));
    return vec3(inside,variation,patternNoise(patternCoordinates(localPosition)*85.));
}
vec3 proceduralShadingNormal(vec3 n,vec3 p,vec2 uv) {
    vec3 b=brickPattern();return patternBump(n,u_relief*(b.x*0.035+b.z*0.002));
}
vec4 proceduralColor(vec4 c,vec3 p,vec3 n,vec2 uv) {
    vec3 b=brickPattern();vec3 brick=u_brickColor.rgb*(1.0-u_variation*b.y)*(0.92+0.08*b.z);
    return vec4(mix(u_mortarColor.rgb,brick,b.x),c.a*mix(u_mortarColor.a,u_brickColor.a,b.x));
}

